def find_shortest_supersequence(s, t):
    # Helper function to check if a string is a valid regular bracket sequence
    def is_valid(seq):
        balance = 0
        for char in seq:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Find the minimum length of the supersequence
    min_length = len(s) + len(t)

    # Try all possible ways to interleave s and t
    from itertools import permutations
    for perm in permutations([s, t]):
        a, b = perm
        # Generate all possible supersequences of a and b
        from itertools import product
        for seq in product(a, b):
            if is_valid(''.join(seq)):
                min_length = min(min_length, len(''.join(seq)))

    # Reconstruct the shortest supersequence
